    +'<div style="pointer-events:auto;text-align:right"><a href="privacy.html" style="font-size:11px;color:var(--muted);text-decoration:none">Privacyverklaring</a> &middot; <a href="voorwaarden.html" style="font-size:11px;color:var(--muted);text-decoration:none">Voorwaarden verkopers/kopers</a> &middot; <a href="platformvoorwaarden.html" style="font-size:11px;color:var(--muted);text-decoration:none">Voorwaarden adviseurs</a></div>'
