// Gefaseerde koper-toegang: vrijgegeven categorieën uit het traject lezen.
// null = "alles vrij" (oude trajecten, backward compat); array = alleen die fase_id's.
function koperCatsVan(t){
  if(!t || t.koper_categorieen==null) return null;
  try{ var c=JSON.parse(t.koper_categorieen); return Array.isArray(c)?c:[]; }catch(e){ return []; }
}

// Modal: begeleider vinkt per DD-categorie aan wat de koper mag inzien
function toonKoperToegangModal(app){
  var t=S.traject||{};
  var fases=(window.FASES&&FASES.length)?FASES:[];
  var huidige=koperCatsVan(t);
  // null (alles) → bij binaire oude vrijgave alles aangevinkt; anders de opgeslagen selectie
  var voorGeselecteerd = huidige===null ? (t.koper_vrijgegeven?fases.map(function(f){return f.id;}):[]) : huidige;
  var ov=document.createElement('div');ov.style.cssText='position:fixed;inset:0;background:rgba(0,0,0,.55);z-index:400;display:flex;align-items:center;justify-content:center;padding:1.5rem';
  var mo=document.createElement('div');mo.setAttribute('role','dialog');mo.setAttribute('aria-modal','true');mo.setAttribute('aria-labelledby','kopertoegang-modal-titel');mo.style.cssText='background:var(--panel);border-radius:10px;padding:1.75rem;max-width:520px;width:100%;max-height:90vh;overflow-y:auto';
  var rijen=fases.map(function(f){
    var aan=voorGeselecteerd.indexOf(f.id)>=0;
    return '<label style="display:flex;align-items:center;gap:10px;padding:9px 12px;border:1px solid var(--border);border-radius:7px;margin-bottom:7px;cursor:pointer;font-size:13px;color:var(--sub)">'
      +'<input type="checkbox" class="kt-cat" value="'+f.id+'"'+(aan?' checked':'')+' style="width:16px;height:16px;accent-color:var(--teal)">'
      +'<span style="font-weight:600;color:#8a8880;min-width:24px">'+esc(f.num||'')+'</span><span>'+esc(f.title||f.id)+'</span></label>';
  }).join('');
  mo.innerHTML='<div id="kopertoegang-modal-titel" style="font-family:Playfair Display,serif;font-size:1.15rem;color:var(--head);font-weight:600;margin-bottom:.25rem">&#128275; Koper-toegang per categorie</div>'
    +'<div style="font-size:12px;color:#8a8880;margin-bottom:1rem">Vink aan welke DD-categorieën de koper mag inzien (velden én documenten). De koper ziet uitsluitend wat hier is vrijgegeven.</div>'
    +'<div style="display:flex;gap:8px;margin-bottom:.85rem"><button id="kt-alles" style="background:transparent;border:1px solid #c8c5bc;padding:5px 12px;border-radius:6px;cursor:pointer;font-size:12px">Alles</button><button id="kt-niets" style="background:transparent;border:1px solid #c8c5bc;padding:5px 12px;border-radius:6px;cursor:pointer;font-size:12px">Niets</button></div>'
    +rijen
    +'<div id="kt-err" style="display:none;color:#e05252;font-size:12px;margin:.5rem 0"></div>'
    +'<div style="display:flex;gap:8px;justify-content:flex-end;margin-top:1rem">'
    +'<button id="kt-ann" style="background:transparent;border:1px solid #c8c5bc;padding:8px 16px;border-radius:6px;cursor:pointer;font-size:13px">Annuleren</button>'
    +'<button id="kt-ok" style="background:#1a7a5e;color:#fff;border:none;padding:8px 16px;border-radius:6px;cursor:pointer;font-size:13px;font-weight:600">Opslaan</button>'
    +'</div>';
  ov.appendChild(mo);document.body.appendChild(ov);
  ov.addEventListener('click',function(e){if(e.target===ov)document.body.removeChild(ov);});
  document.getElementById('kt-ann').onclick=function(){document.body.removeChild(ov);};
  document.getElementById('kt-alles').onclick=function(){mo.querySelectorAll('.kt-cat').forEach(function(c){c.checked=true;});};
  document.getElementById('kt-niets').onclick=function(){mo.querySelectorAll('.kt-cat').forEach(function(c){c.checked=false;});};
  document.getElementById('kt-ok').onclick=async function(){
    var btn=this;btn.disabled=true;btn.textContent='Opslaan...';
    var errEl=document.getElementById('kt-err');errEl.style.display='none';
    var cats=Array.prototype.slice.call(mo.querySelectorAll('.kt-cat:checked')).map(function(c){return c.value;});
    async function verstuur(force){
      var url=WORKER+'/mna/koper-categorieen/'+S.traject.id+(force?'?force=1':'');
      return fetch(url,{method:'POST',headers:{'Content-Type':'application/json','x-tussen-key':S._bgKey},body:JSON.stringify({categorieen:cats})}).then(function(x){return x.json();}).catch(function(){return{};});
    }
    var r=await verstuur(false);
    if(r.nda_niet_getekend){
      if(confirm('⚠ De NDA is nog NIET getekend.\n\nKoper krijgt toegang zonder geheimhoudingsovereenkomst. Toch vrijgeven?')){ r=await verstuur(true); }
      else { btn.disabled=false;btn.textContent='Opslaan';return; }
    }
    if(r.ok){
      S.traject.koper_categorieen=JSON.stringify(cats);
      S.traject.koper_vrijgegeven=cats.length?1:0;
      secAuditLog('koper_categorieen_bijgewerkt',{aantal:cats.length});
      document.body.removeChild(ov);
      toast(cats.length?('Koper-toegang bijgewerkt ('+cats.length+' categorie'+(cats.length===1?'':'ën')+')'):'Koper-toegang volledig ingetrokken','ok');
      renderBegeleiderDashboard(app);
    } else { errEl.style.display='block';errEl.textContent=r.error||'Fout bij opslaan';btn.disabled=false;btn.textContent='Opslaan'; }
  };
}

function toonGroepsstructuurModal(app){
  var ov=document.createElement('div');ov.style.cssText='position:fixed;inset:0;background:rgba(0,0,0,.55);z-index:400;display:flex;align-items:center;justify-content:center;padding:1.5rem';
  var mo=document.createElement('div');mo.setAttribute('role','dialog');mo.setAttribute('aria-modal','true');mo.setAttribute('aria-labelledby','groepsstructuur-modal-titel');mo.style.cssText='background:var(--panel);border-radius:10px;padding:1.75rem;max-width:520px;width:100%;max-height:90vh;overflow-y:auto';
  mo.innerHTML='<div id="groepsstructuur-modal-titel" style="font-family:Playfair Display,serif;font-size:1.15rem;color:var(--head);font-weight:600;margin-bottom:.25rem">&#127970; Groepsstructuur</div>'
    +'<div style="font-size:12px;color:#8a8880;margin-bottom:1rem">Betreft dit traject een holding met meerdere werkmaatschappijen? Registreer hier de aparte entiteiten — documenten van deze bedrijven worden dan niet meer afgewezen als "ander bedrijf", en blijven traceerbaar in de dataroom.</div>'
    +'<div id="gs-lijst" style="margin-bottom:1rem;font-size:13px;color:#8a8880;font-style:italic">Laden...</div>'
    +'<div style="display:flex;gap:8px;margin-bottom:.5rem">'
    +'<input type="text" id="gs-naam" placeholder="Naam entiteit" style="flex:2;background:#f0eeea;color:#2a2825;border:1px solid #c8c5bc;border-radius:6px;padding:7px 11px;font-size:13px">'
    +'<input type="text" id="gs-kvk" placeholder="KvK (optioneel)" style="flex:1;background:#f0eeea;color:#2a2825;border:1px solid #c8c5bc;border-radius:6px;padding:7px 11px;font-size:13px">'
    +'<button id="gs-toevoegen" style="background:#1a7a5e;color:#fff;border:none;padding:7px 14px;border-radius:6px;cursor:pointer;font-size:13px;font-weight:600;white-space:nowrap">+ Toevoegen</button>'
    +'</div>'
    +'<label style="display:flex;align-items:flex-start;gap:6px;font-size:11px;color:var(--muted);margin-bottom:1rem;cursor:pointer">'
    +'<input type="checkbox" id="gs-holding" style="margin-top:2px">'
    +'<span>Dit is de overkoepelende <strong>holding</strong>, niet een werkmaatschappij — bijv. bij het toevoegen van de holding zelf naast de werkmaatschappijen. De holding telt niet apart mee in het groepstotaal (haar eigen jaarrekening is in Nederland vrijwel altijd al de geconsolideerde jaarrekening, die werkmaatschappijen dus al bevat).</span>'
    +'</label>'
    +'<div id="gs-err" style="display:none;color:#e05252;font-size:12px;margin:.5rem 0"></div>'
    +'<div style="display:flex;justify-content:flex-end;margin-top:1rem">'
    +'<button id="gs-sluiten" style="background:transparent;border:1px solid #c8c5bc;padding:8px 16px;border-radius:6px;cursor:pointer;font-size:13px">Sluiten</button>'
    +'</div>';
  ov.appendChild(mo);document.body.appendChild(ov);
  ov.addEventListener('click',function(e){if(e.target===ov)document.body.removeChild(ov);});
  document.getElementById('gs-sluiten').onclick=function(){document.body.removeChild(ov);};

  async function laadLijst(){
    var lijstEl=document.getElementById('gs-lijst');
    lijstEl.textContent='Laden...';
    var rows=await fetch(WORKER+'/mna/entiteiten/'+S.code).then(function(r){return r.json();}).catch(function(){return [];});
    if(!rows||!rows.length){lijstEl.innerHTML='<span style="font-style:italic">Nog geen entiteiten geregistreerd — dit traject wordt behandeld als één bedrijf.</span>';return;}
    lijstEl.style.fontStyle='normal';
    lijstEl.innerHTML=rows.map(function(r){
      var holdingBadge=r.rol==='holding'?' <span style="font-size:9px;font-weight:700;color:var(--gold-dark);background:var(--gold-bg);border-radius:8px;padding:1px 6px;margin-left:4px" title="Telt niet apart mee in het groepstotaal">HOLDING</span>':'';
      return '<div style="display:flex;align-items:center;gap:8px;padding:7px 10px;border:1px solid var(--border);border-radius:7px;margin-bottom:6px">'
        +'<div style="flex:1"><div style="font-size:13px;color:var(--sub)">'+esc(r.naam)+holdingBadge+'</div>'+(r.kvk?'<div style="font-size:11px;color:var(--muted)">KvK '+esc(r.kvk)+'</div>':'')+'</div>'
        +'<button class="gs-verwijder" data-id="'+esc(r.id)+'" style="background:transparent;border:1px solid #c8c5bc;color:#e05252;border-radius:6px;padding:4px 10px;cursor:pointer;font-size:12px">Verwijderen</button>'
        +'</div>';
    }).join('');
    lijstEl.querySelectorAll('.gs-verwijder').forEach(function(btn){
      btn.onclick=async function(){
        await fetch(WORKER+'/mna/entiteiten/'+S.code,{method:'POST',headers:{'Content-Type':'application/json','x-tussen-key':S._bgKey},body:JSON.stringify({actie:'verwijderen',id:btn.dataset.id})});
        laadLijst();
      };
    });
  }
  document.getElementById('gs-toevoegen').onclick=async function(){
    var btn=this;var naamEl=document.getElementById('gs-naam');var kvkEl=document.getElementById('gs-kvk');var errEl=document.getElementById('gs-err');var holdingEl=document.getElementById('gs-holding');
    errEl.style.display='none';
    var naam=naamEl.value.trim();
    if(!naam){errEl.textContent='Naam is verplicht.';errEl.style.display='block';return;}
    btn.disabled=true;btn.textContent='...';
    var r=await fetch(WORKER+'/mna/entiteiten/'+S.code,{method:'POST',headers:{'Content-Type':'application/json','x-tussen-key':S._bgKey},body:JSON.stringify({naam:naam,kvk:kvkEl.value.trim(),rol:holdingEl.checked?'holding':'werkmaatschappij'})}).then(function(x){return x.json();}).catch(function(){return {};});
    btn.disabled=false;btn.textContent='+ Toevoegen';
    if(r.ok){naamEl.value='';kvkEl.value='';holdingEl.checked=false;laadLijst();}
    else{errEl.textContent=r.error||'Fout bij opslaan';errEl.style.display='block';}
  };
  laadLijst();
}

// Partnerregister: partners eenmalig vastleggen (naam, leeftijd, veranderbereidheid,
// opvolgingskandidaat, gekoppelde entiteiten, omzet incl. onderliggend team) i.p.v. deze vragen
// per entiteit te herhalen — dezelfde partner kan bij meerdere werkmaatschappijen horen (Marcel,
// 25 juli 2026). Additief: de bestaande per-entiteit velden (leeftijd/veranderbereidheid/opvolging/
// omzet per partner) blijven ongewijzigd staan — geen dataverlies, geen gok naar wie welke oude
// waarde was. "Omzet die aan de partner hangt" is bewust incl. onderliggend team, niet alleen zijn
// eigen declarabele productie — bij vertrek van de partner is dát het omzetrisico voor de koper.
function toonPartnersModal(app){
  var pt=getPartnerTerm();
  var ov=document.createElement('div');ov.style.cssText='position:fixed;inset:0;background:rgba(0,0,0,.55);z-index:400;display:flex;align-items:center;justify-content:center;padding:1.5rem';
  var mo=document.createElement('div');mo.setAttribute('role','dialog');mo.setAttribute('aria-modal','true');mo.setAttribute('aria-labelledby','partners-modal-titel');mo.style.cssText='background:var(--panel);border-radius:10px;padding:1.75rem;max-width:560px;width:100%;max-height:90vh;overflow-y:auto';
  mo.innerHTML='<div id="partners-modal-titel" style="font-family:Playfair Display,serif;font-size:1.15rem;color:var(--head);font-weight:600;margin-bottom:.25rem">&#129489;&#8205;&#128188; '+esc(pt.titel)+'</div>'
    +'<div style="font-size:12px;color:#8a8880;margin-bottom:1rem">Leg elke '+esc(pt.enkel)+' één keer vast, ook als deze bij meerdere entiteiten werkt. "Omzet die aan de '+esc(pt.enkel)+' hangt" is de omzet incl. het onderliggend team — het bedrag dat risico loopt als deze '+esc(pt.enkel)+' vertrekt, niet alleen zijn eigen declarabele productie.</div>'
    +'<div id="pt-reconciliatie"></div>'
    +'<div id="pt-lijst" style="margin-bottom:1rem;font-size:13px;color:#8a8880;font-style:italic">Laden...</div>'
    +'<div style="border-top:1px solid #e5e2d8;padding-top:.85rem;margin-top:.5rem">'
    +'<div style="display:flex;gap:8px;margin-bottom:6px">'
    +'<input type="text" id="pt-naam" placeholder="Naam '+esc(pt.enkel)+'" style="flex:2;background:#f0eeea;color:#2a2825;border:1px solid #c8c5bc;border-radius:6px;padding:7px 11px;font-size:13px">'
    +'<input type="text" id="pt-leeftijd" placeholder="Leeftijd" style="flex:1;background:#f0eeea;color:#2a2825;border:1px solid #c8c5bc;border-radius:6px;padding:7px 11px;font-size:13px">'
    +'</div>'
    +'<div style="display:flex;gap:8px;margin-bottom:6px">'
    +'<input type="text" id="pt-verandering" placeholder="Veranderbereidheid" style="flex:1;background:#f0eeea;color:#2a2825;border:1px solid #c8c5bc;border-radius:6px;padding:7px 11px;font-size:13px">'
    +'<input type="text" id="pt-opvolging" placeholder="Opvolgingskandidaat" style="flex:1;background:#f0eeea;color:#2a2825;border:1px solid #c8c5bc;border-radius:6px;padding:7px 11px;font-size:13px">'
    +'<input type="text" id="pt-omzet" placeholder="Omzet incl. team (€)" style="flex:1;background:#f0eeea;color:#2a2825;border:1px solid #c8c5bc;border-radius:6px;padding:7px 11px;font-size:13px">'
    +'</div>'
    +(isMaatschap()?'<div style="display:flex;gap:8px;margin-bottom:6px"><input type="text" id="pt-winstaandeel" placeholder="Winstaandeel deze maat (%)" style="flex:1;background:#f0eeea;color:#2a2825;border:1px solid #c8c5bc;border-radius:6px;padding:7px 11px;font-size:13px"></div>':'')
    +'<div id="pt-entiteiten" style="font-size:12px;color:#8a8880;margin-bottom:8px">Gekoppelde entiteiten: <span style="font-style:italic">laden...</span></div>'
    +'<button id="pt-toevoegen" style="background:#1a7a5e;color:#fff;border:none;padding:7px 14px;border-radius:6px;cursor:pointer;font-size:13px;font-weight:600">+ Toevoegen</button>'
    +'</div>'
    +'<div id="pt-err" style="display:none;color:#e05252;font-size:12px;margin:.5rem 0"></div>'
    +'<div style="display:flex;justify-content:flex-end;margin-top:1rem">'
    +'<button id="pt-sluiten" style="background:transparent;border:1px solid #c8c5bc;padding:8px 16px;border-radius:6px;cursor:pointer;font-size:13px">Sluiten</button>'
    +'</div>';
  ov.appendChild(mo);document.body.appendChild(ov);
  ov.addEventListener('click',function(e){if(e.target===ov)document.body.removeChild(ov);});
  document.getElementById('pt-sluiten').onclick=function(){document.body.removeChild(ov);};

  async function laadEntiteitenCheckboxen(){
    var rows=(S._entiteiten&&S._entiteiten.length)?S._entiteiten:await fetch(WORKER+'/mna/entiteiten/'+S.code).then(function(r){return r.json();}).catch(function(){return [];});
    var el=document.getElementById('pt-entiteiten');
    if(!rows||!rows.length){el.innerHTML='Gekoppelde entiteiten: <span style="font-style:italic">geen entiteiten geregistreerd — deze partner geldt dan voor het hele traject.</span>';return;}
    el.innerHTML='Gekoppelde entiteiten:<div style="display:flex;flex-wrap:wrap;gap:10px;margin-top:4px">'
      +rows.map(function(r){return '<label style="display:flex;align-items:center;gap:4px;cursor:pointer"><input type="checkbox" class="pt-ent-chk" value="'+esc(r.id)+'"> '+esc(r.naam)+'</label>';}).join('')
      +'</div>';
  }

  // Audit-fix P1 (25 juli 2026, vijfde ronde): het partnerregister en de oudere, losse DD-velden
  // partner_aantalP/partner_omzetPerP zijn twee niet-gesynchroniseerde databronnen — de waardering
  // leest nog steeds de oude velden (bewust niet automatisch overschreven, zie hierboven "geen
  // gok naar wie welke oude waarde was"). Puur informatieve, niet-blokkerende vergelijking, zodat
  // een afwijking hier zichtbaar is i.p.v. stil te blijven bestaan.
  function toonReconciliatie(rows){
    var el=document.getElementById('pt-reconciliatie');
    if(!rows||!rows.length){el.innerHTML='';return;}
    var aantalRegister=rows.length;
    var omzetRegister=rows.reduce(function(sum,r){return sum+(parseFloat(r.omzet_incl_team)||0);},0);
    var aantalIngevuld=parseFloat(S.data['partner_aantalP'])||null;
    var omzetIngevuld=null;var omzetRaw=S.data['partner_omzetPerP'];
    if(omzetRaw){var n=parseFloat(String(omzetRaw).replace(/[^0-9.,]/g,'').replace(',','.'));if(!isNaN(n))omzetIngevuld=n;}
    var verschillen=[];
    if(aantalIngevuld!==null&&aantalIngevuld!==aantalRegister)verschillen.push('aantal '+pt.meer+': DD-veld zegt '+aantalIngevuld+', register zegt '+aantalRegister);
    if(omzetIngevuld!==null&&Math.abs(omzetIngevuld-omzetRegister)>1)verschillen.push('omzet: DD-veld zegt €'+omzetIngevuld.toLocaleString('nl-NL')+', register (som incl. team) zegt €'+omzetRegister.toLocaleString('nl-NL'));
    if(!verschillen.length){el.innerHTML='';return;}
    el.innerHTML='<div style="background:var(--gold-bg);border:1px solid var(--gold);border-radius:6px;padding:8px 12px;margin-bottom:.85rem;font-size:12px;color:var(--sub)">'
      +'&#9888; Het register met '+esc(pt.meer)+' wijkt af van de ingevulde DD-velden (mensen-fase van de due diligence) — de waardering gebruikt nog steeds de DD-velden, niet dit register. '+esc(verschillen.join('; '))+'. Werk beide bij als één van de twee verouderd is.'
      +'</div>';
  }
  async function laadLijst(){
    var lijstEl=document.getElementById('pt-lijst');
    lijstEl.textContent='Laden...';
    var rows=await fetch(WORKER+'/mna/partners/'+S.code).then(function(r){return r.json();}).catch(function(){return [];});
    toonReconciliatie(rows);
    if(!rows||!rows.length){lijstEl.innerHTML='<span style="font-style:italic">Nog geen '+esc(pt.meer)+' geregistreerd.</span>';return;}
    lijstEl.style.fontStyle='normal';
    lijstEl.innerHTML=rows.map(function(r){
      var entNamen=(r.entiteit_ids||[]).map(function(id){var e=(S._entiteiten||[]).find(function(x){return x.id===id;});return e?e.naam:id;}).join(', ');
      return '<div style="display:flex;align-items:flex-start;gap:8px;padding:7px 10px;border:1px solid var(--border);border-radius:7px;margin-bottom:6px">'
        +'<div style="flex:1">'
        +'<div style="font-size:13px;color:var(--sub);font-weight:600">'+esc(r.naam)+(r.leeftijd?' &middot; '+esc(r.leeftijd)+' jaar':'')+'</div>'
        +(r.veranderbereidheid?'<div style="font-size:11px;color:var(--muted)">Veranderbereidheid: '+esc(r.veranderbereidheid)+'</div>':'')
        +(r.opvolgingskandidaat?'<div style="font-size:11px;color:var(--muted)">Opvolging: '+esc(r.opvolgingskandidaat)+'</div>':'')
        +(r.omzet_incl_team?'<div style="font-size:11px;color:var(--muted)">Omzet incl. team: &euro;'+esc(Number(r.omzet_incl_team).toLocaleString('nl-NL'))+'</div>':'')
        +(r.winstaandeel_pct?'<div style="font-size:11px;color:var(--muted)">Winstaandeel: '+esc(r.winstaandeel_pct)+'%</div>':'')
        +(entNamen?'<div style="font-size:11px;color:var(--teal)">'+esc(entNamen)+'</div>':'')
        +'</div>'
        +'<button class="pt-verwijder" data-id="'+esc(r.id)+'" style="background:transparent;border:1px solid #c8c5bc;color:#e05252;border-radius:6px;padding:4px 10px;cursor:pointer;font-size:12px">Verwijderen</button>'
        +'</div>';
    }).join('');
    lijstEl.querySelectorAll('.pt-verwijder').forEach(function(btn){
      btn.onclick=async function(){
        await fetch(WORKER+'/mna/partners/'+S.code,{method:'POST',headers:{'Content-Type':'application/json','x-tussen-key':S._bgKey},body:JSON.stringify({actie:'verwijderen',id:btn.dataset.id})});
        laadLijst();
      };
    });
  }
  document.getElementById('pt-toevoegen').onclick=async function(){
    var btn=this;
    var naamEl=document.getElementById('pt-naam'),leeftijdEl=document.getElementById('pt-leeftijd'),verEl=document.getElementById('pt-verandering'),opvEl=document.getElementById('pt-opvolging'),omzetEl=document.getElementById('pt-omzet'),winstEl=document.getElementById('pt-winstaandeel');
    var errEl=document.getElementById('pt-err');errEl.style.display='none';
    var naam=naamEl.value.trim();
    if(!naam){errEl.textContent='Naam is verplicht.';errEl.style.display='block';return;}
    var entIds=Array.prototype.slice.call(document.querySelectorAll('.pt-ent-chk:checked')).map(function(c){return c.value;});
    btn.disabled=true;btn.textContent='...';
    var r=await fetch(WORKER+'/mna/partners/'+S.code,{method:'POST',headers:{'Content-Type':'application/json','x-tussen-key':S._bgKey},body:JSON.stringify({naam:naam,leeftijd:leeftijdEl.value.trim(),veranderbereidheid:verEl.value.trim(),opvolgingskandidaat:opvEl.value.trim(),omzet_incl_team:omzetEl.value.trim(),winstaandeel_pct:winstEl?winstEl.value.trim():'',entiteit_ids:entIds})}).then(function(x){return x.json();}).catch(function(){return {};});
    btn.disabled=false;btn.textContent='+ Toevoegen';
    if(r.ok){naamEl.value='';leeftijdEl.value='';verEl.value='';opvEl.value='';omzetEl.value='';if(winstEl)winstEl.value='';document.querySelectorAll('.pt-ent-chk').forEach(function(c){c.checked=false;});laadLijst();}
    else{errEl.textContent=r.error||'Fout bij opslaan';errEl.style.display='block';}
  };
  laadEntiteitenCheckboxen();
  laadLijst();
}

// Risicoclassificatie per DD-bevinding (23 aug 2026) — begeleider-only, verkoper ziet dit nooit.
// Enums moeten exact overeenkomen met RISICOKLASSEN/MA_ACTIES in backend/worker/02-config-constanten.js
// (de server valideert hier ook tegen, dit is alleen voor de UI).
var RISICOKLASSEN = ['Critical','High','Medium','Low','Info'];
var MA_ACTIES = ['Geen actie','Nader onderzoeken','Prijs aanpassen','Garantie opnemen','Indemnity opnemen','Escrow','CP voor closing','Earn-out','Stop transactie'];
var RISICO_KLEUR = {Critical:'var(--red)',High:'var(--red)',Medium:'var(--gold)',Low:'var(--teal)',Info:'var(--muted)'};

async function laadRisicoBadges(){
  var d=await fetch(WORKER+'/mna/infofase/'+S.code,{headers:{'x-tussen-key':S._bgKey||''}}).then(function(r){return r.json();}).catch(function(){return{ok:false};});
  S._beoordelingen=(d&&d.ok&&d.beoordelingen)||[];
  var perFase={};
  S._beoordelingen.forEach(function(b){
    if(!b.risicoklasse)return;
    perFase[b.fase]=perFase[b.fase]||{};
    perFase[b.fase][b.risicoklasse]=(perFase[b.fase][b.risicoklasse]||0)+1;
  });
  Object.keys(perFase).forEach(function(faseId){
    var el=document.getElementById('bg-risico-badge-'+faseId);
    if(!el)return;
    var hoogste=RISICOKLASSEN.find(function(k){return perFase[faseId][k];});
    var totaal=Object.keys(perFase[faseId]).reduce(function(a,k){return a+perFase[faseId][k];},0);
    if(hoogste)el.innerHTML='<span style="font-size:10px;font-weight:600;padding:2px 7px;border-radius:10px;background:'+RISICO_KLEUR[hoogste]+';color:#fff">'+totaal+' bevinding'+(totaal===1?'':'en')+'</span>';
  });
}

// Vult de closing-checklist-voortgang in de documentflow (de overige 3 niet-ondertekenbare stappen
// — Bieding/Dealvoorstel/SPA — hebben geen betrouwbare "gegenereerd"-status om op te halen: die
// worden pas als documentversie bewaard zodra ze daadwerkelijk verstuurd worden, niet bij het openen
// van het scherm, dus daar blijft de statische tekst uit stapRij() staan).
async function laadDocFlowStatus(){
  var el=document.querySelector('.stap-status[data-doc="bg-closing-actie"]');
  if(!el)return;
  var d=await fetch(WORKER+'/mna/closing-checklist/'+S.code,{headers:{'x-tussen-key':S._bgKey||''}}).then(function(r){return r.json();}).catch(function(){return{ok:false};});
  if(!d.ok)return;
  var totaal=0,af=0;
  (d.checklist||[]).forEach(function(cat){cat.items.forEach(function(){totaal++;});});
  Object.keys(d.status||{}).forEach(function(k){if(d.status[k]&&d.status[k].aangevinkt)af++;});
  el.innerHTML=af===totaal&&totaal>0
    ?'<span style="color:var(--teal)">&#10003; '+af+' / '+totaal+' afgerond</span>'
    :af>0?'<span style="color:var(--gold-dark)">'+af+' / '+totaal+' afgerond</span>':totaal+' punten — nog niet gestart';
}

// Modal: per DD-fase de standaard rode-vlaggen uit het sectorprofiel (FASES[x].redflags) tonen als
// classificeerbare bevindingen, plus eigen bevindingen kunnen toevoegen. Elke rij is los opslaanbaar
// (categorie+fase is de unieke sleutel in mna_beoordelingen, zie worker/19-info-fases.js).
async function toonRisicoModal(faseId){
  if(S.modules&&S.modules.ai_analyse===false){toast('Module AI-analyse niet actief. Neem contact op met ' + BRAND.kort + '.','err');return;}
  var fase=(FASES||[]).find(function(f){return f.id===faseId;});
  if(!fase)return;
  var ov=document.createElement('div');
  ov.style.cssText='position:fixed;inset:0;background:rgba(0,0,0,.75);z-index:2000;display:flex;align-items:center;justify-content:center;padding:1.5rem';
  var mo=document.createElement('div');
  mo.setAttribute('role','dialog');mo.setAttribute('aria-modal','true');
  mo.style.cssText='background:var(--panel);border:1px solid var(--border2);border-radius:var(--r2);padding:2rem;max-width:680px;width:100%;max-height:90vh;overflow-y:auto';
  mo.innerHTML='<div style="font-family:Playfair Display,serif;font-size:1.2rem;color:var(--head);font-weight:600;margin-bottom:.4rem">&#128681; Risicobeoordeling &mdash; '+esc(fase.title)+'</div>'
    +'<div style="font-size:11px;color:var(--muted);margin-bottom:1rem">Alleen zichtbaar voor u &mdash; de verkoper ziet dit niet. Risicoklasse en vervolgactie zijn optioneel; laat leeg als u nog geen oordeel heeft (nooit een gok invullen).</div>'
    +'<div id="rk-lijst"></div>'
    +'<div style="border-top:1px solid var(--border);margin-top:1rem;padding-top:1rem">'
    +'<div style="font-size:11px;font-weight:600;color:var(--muted);margin-bottom:6px">+ Eigen bevinding toevoegen</div>'
    +'<div style="display:flex;gap:8px">'
    +'<input type="text" id="rk-nieuw-cat" placeholder="Korte omschrijving van de bevinding" style="flex:1;background:var(--card);border:1px solid var(--border2);border-radius:var(--r);padding:8px 10px;font-size:12px;color:var(--sub)">'
    +'<button id="rk-nieuw-toevoegen" class="btn-outline btn-sm" style="font-size:11px">+ Toevoegen</button>'
    +'</div></div>'
    +'<div style="display:flex;justify-content:flex-end;margin-top:1.25rem">'
    +'<button id="rk-sluiten" class="btn-ghost" style="font-size:12px;padding:7px 14px">Sluiten</button>'
    +'</div>';
  ov.appendChild(mo);
  document.body.appendChild(ov);
  document.getElementById('rk-sluiten').onclick=function(){document.body.removeChild(ov);};

  function rijHtml(categorie,b){
    b=b||{};
    var opties=['<option value="">&mdash; geen &mdash;</option>'].concat(RISICOKLASSEN.map(function(k){return '<option value="'+k+'"'+(b.risicoklasse===k?' selected':'')+'>'+k+'</option>';})).join('');
    var actieOpties=['<option value="">&mdash; geen &mdash;</option>'].concat(MA_ACTIES.map(function(a){return '<option value="'+esc(a)+'"'+(b.ma_actie===a?' selected':'')+'>'+esc(a)+'</option>';})).join('');
    var bestaandeAi=null;
    if(b.ai_analyse){try{bestaandeAi=JSON.parse(b.ai_analyse);}catch(e){}}
    return '<div class="rk-rij" data-cat="'+esc(categorie)+'" style="background:var(--card);border:1px solid var(--border);border-radius:var(--r);padding:10px;margin-bottom:8px">'
      +'<div style="display:flex;justify-content:space-between;align-items:flex-start;gap:8px;margin-bottom:6px">'
      +'<div style="font-size:12px;color:var(--sub);font-weight:600">'+esc(categorie)+'</div>'
      +'<button class="rk-ai-vraag btn-outline btn-sm" style="font-size:10px;padding:2px 8px;white-space:nowrap">&#129302; AI-suggestie</button>'
      +'</div>'
      +'<div class="rk-ai-out" style="display:'+(bestaandeAi?'block':'none')+';background:var(--gold-bg);border:1px solid var(--gold);border-radius:6px;padding:8px;margin-bottom:6px;font-size:11px;color:var(--sub);line-height:1.6">'
      +(bestaandeAi?renderAiSuggestie(bestaandeAi):'')+'</div>'
      +'<div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:6px">'
      +'<select class="rk-klasse" style="font-size:12px;padding:6px;border-radius:6px;border:1px solid var(--border2);background:var(--panel);color:var(--sub)">'+opties+'</select>'
      +'<select class="rk-actie" style="font-size:12px;padding:6px;border-radius:6px;border:1px solid var(--border2);background:var(--panel);color:var(--sub)">'+actieOpties+'</select>'
      +'</div>'
      +'<textarea class="rk-notitie" placeholder="Toelichting (optioneel)" style="width:100%;min-height:44px;background:var(--panel);border:1px solid var(--border2);border-radius:6px;padding:6px 8px;font-size:12px;color:var(--sub)">'+esc(b.adviseur_notitie||'')+'</textarea>'
      +'<div style="display:flex;justify-content:flex-end;align-items:center;margin-top:6px">'
      +'<span class="rk-status" style="font-size:11px;margin-right:8px"></span>'
      +'<button class="rk-opslaan btn-sm" style="font-size:11px;padding:4px 12px;border-radius:6px;border:1px solid var(--border2);background:transparent;color:var(--sub);cursor:pointer">Opslaan</button>'
      +'</div></div>';
  }

  // Toont de AI-analyse als leestekst — vult NOOIT zelf risicoklasse/ma_actie in, dat blijft
  // begeleider-oordeel (GOUDEN STANDAARD). Score is een hulpmiddel, geen automatische classificatie.
  function renderAiSuggestie(ai){
    var delen=[];
    if(ai.analyse)delen.push('<div><strong>Analyse:</strong> '+esc(ai.analyse)+'</div>');
    if(ai.risicos)delen.push('<div><strong>Risico\'s:</strong> '+esc(ai.risicos)+'</div>');
    if(ai.ontbreekt)delen.push('<div><strong>Ontbreekt nog:</strong> '+esc(ai.ontbreekt)+'</div>');
    if(ai.score!=null)delen.push('<div><strong>AI-score:</strong> '+esc(String(ai.score))+'/10 &mdash; ter indicatie, bepaalt niet zelf de risicoklasse.</div>');
    return delen.join('') || '<em>Geen AI-analyse beschikbaar.</em>';
  }

  function bindRij(el,categorie){
    el.querySelector('.rk-opslaan').onclick=async function(){
      var btn=this,statusEl=el.querySelector('.rk-status');
      btn.disabled=true;btn.textContent='...';
      var body={code:S.code,fase:faseId,categorie:categorie,bevinding:'',adviseur_notitie:el.querySelector('.rk-notitie').value,risicoklasse:el.querySelector('.rk-klasse').value||null,ma_actie:el.querySelector('.rk-actie').value||null};
      var r=await fetch(WORKER+'/mna/beoordeling/opslaan',{method:'POST',headers:{'Content-Type':'application/json','x-tussen-key':S._bgKey||''},body:JSON.stringify(body)}).then(function(x){return x.json();}).catch(function(){return{};});
      btn.disabled=false;btn.textContent='Opslaan';
      statusEl.style.color=r.ok?'var(--teal)':'var(--red)';
      statusEl.textContent=r.ok?'Opgeslagen':(r.error||'Mislukt');
      if(r.ok)laadRisicoBadges();
    };
    el.querySelector('.rk-ai-vraag').onclick=async function(){
      if(!aiAnalyseAan){toast('Module AI-analyse niet actief. Neem contact op met ' + BRAND.kort + '.','err');return;}
      var btn=this,outEl=el.querySelector('.rk-ai-out');
      btn.disabled=true;btn.textContent='Bezig...';
      outEl.style.display='block';
      outEl.innerHTML='<em>AI-analyse wordt opgehaald&hellip;</em>';
      var r=await fetch(WORKER+'/mna/beoordeling/ai',{method:'POST',headers:{'Content-Type':'application/json','x-tussen-key':S._bgKey||''},body:JSON.stringify({code:S.code,fase:faseId,categorie:categorie})}).then(function(x){return x.json();}).catch(function(){return{};});
      btn.disabled=false;btn.innerHTML='&#129302; AI-suggestie';
      if(r.ok&&r.analyse){outEl.innerHTML=renderAiSuggestie(r.analyse);}
      else{outEl.innerHTML='<span style="color:var(--red)">'+esc(r.error||'AI-analyse mislukt')+'</span>';}
    };
  }

  function render(){
    var lijstEl=document.getElementById('rk-lijst');
    var bestaand=(S._beoordelingen||[]).filter(function(b){return b.fase===faseId;});
    var html='';
    (fase.redflags||[]).forEach(function(cat){
      var b=bestaand.find(function(x){return x.categorie===cat;});
      html+=rijHtml(cat,b);
    });
    bestaand.filter(function(b){return (fase.redflags||[]).indexOf(b.categorie)===-1;}).forEach(function(b){
      html+=rijHtml(b.categorie,b);
    });
    lijstEl.innerHTML=html||'<div style="font-size:12px;color:var(--muted);font-style:italic">Geen standaard aandachtspunten voor deze fase.</div>';
    lijstEl.querySelectorAll('.rk-rij').forEach(function(el){bindRij(el,el.dataset.cat);});
  }
  render();

  document.getElementById('rk-nieuw-toevoegen').onclick=function(){
    var inp=document.getElementById('rk-nieuw-cat');
    var cat=inp.value.trim();
    if(!cat)return;
    inp.value='';
    var lijstEl=document.getElementById('rk-lijst');
    var wrap=document.createElement('div');
    wrap.innerHTML=rijHtml(cat,null);
    var el=wrap.firstChild;
    lijstEl.appendChild(el);
    bindRij(el,cat);
  };
}

// Opent het dossier op een specifieke fase (het gewone invulscherm, S.screen='main') — de begeleider-
// dashboard hierboven toonde de DD-voortgang tot 18 aug 2026 alleen read-only, zonder enige knop naar
// dit scherm. Daardoor waren documentupload, bankmutaties-upload en de red-flag-analyse (allemaal wél
// gebouwd voor de begeleider-rol, zie isTussen()-checks) in de praktijk nooit bereikbaar via de UI.
function openBegeleiderFase(faseId){
  var idx=FASES.findIndex(function(f){return f.id===faseId;});
  S.screen='main';
  S.fase=idx>=0?idx:0;
  if(!DOCS[faseId])loadDocsForFase(faseId);
  if(faseId==='financieel'){
    if(BANKMUTATIES===null)laadBankmutaties();
    if(BANKMUTATIES_ANALYSE===null)laadRedFlagAnalyse();
  }
  renderApp();
}

